param([int[]]$SeedIndices=(1..10),[int]$MaxParallel=8)
$ErrorActionPreference='Stop';$workspace=Split-Path -Parent $PSScriptRoot;$matlab=(Get-Command matlab).Source
$logDir=Join-Path $PSScriptRoot 'no_detuning_disorder_logs_20260810';New-Item -ItemType Directory -Force -Path $logDir|Out-Null
$pending=[System.Collections.Generic.Queue[int]]::new();foreach($id in $SeedIndices){$pending.Enqueue($id)};$running=@();$completed=@()
while($pending.Count-gt0-or$running.Count-gt0){while($pending.Count-gt0-and$running.Count-lt$MaxParallel){$id=$pending.Dequeue();$out=Join-Path $logDir ("seed{0:D2}.out.log"-f$id);$err=Join-Path $logDir ("seed{0:D2}.err.log"-f$id);if((Test-Path $out)-or(Test-Path $err)){throw "Collision $id"};$batch="KERR_NO_DISORDER_SEED_INDEX=$id;run(fullfile(pwd,'Figure 3','run_narma_no_detuning_disorder_seed_20260810.m'));";$p=Start-Process $matlab -ArgumentList "-singleCompThread -batch `"$batch`"" -WorkingDirectory $workspace -WindowStyle Hidden -PassThru -RedirectStandardOutput $out -RedirectStandardError $err;$running+=[pscustomobject]@{Id=$id;Process=$p};};Start-Sleep -Seconds 3;$still=@();foreach($r in $running){if($r.Process.HasExited){$r.Process.WaitForExit();$r.Process.Refresh();$completed+=[pscustomobject]@{Seed=$r.Id;Exit=$r.Process.ExitCode}}else{$still+=$r}};$running=$still}
$failed=@($completed|Where-Object{$_.Exit-ne0});if($failed.Count){throw "No-disorder failures: $($failed.Seed -join ', ')"};'NO_DETUNING_DISORDER_PARALLEL_PASS'
